import React, {useState} from 'react'

export default function TextForm(props) {
    const a = "new text";
    const [text, setText] = useState('Enter Text Here..');
    //text = "New Text"       wrong way to change the state value
    //setText("New Text");    correct way to change the value of state value
    
    const handleupClick = ()=>{
        console.log("Uppercase was Clicked!")
        //setText("Khuzaima");
        a = "next text updated";
    }

    const handleonChange =()=>{
        console.log("On Change");
    }

  return (
    <div>
        <h1>{props.heading}</h1>
      <div className='mb-3'>
    <textarea className="form-control" value={a} onChange={handleonChange} id="mybox" rows="3"></textarea>
     </div>
     <button className="btn btn-primary" onClick={handleupClick}>Convert to UpperCase</button>
    </div>
  )
}
